def spacing(paragraph, before=0, after=0, line="240"):
    pPr = paragraph._p.get_or_add_pPr()
    node = pPr.find(qn("w:spacing"))
    if node is None:
        node = OxmlElement("w:spacing")
        pPr.append(node)
    node.set(qn("w:before"), str(before))
    node.set(qn("w:after"), str(after))
    node.set(qn("w:line"), line)
    node.set(qn("w:lineRule"), "auto")


def indent(paragraph, left="-396", left_chars="-165", first="792", first_chars="283", right="0"):
    pPr = paragraph._p.get_or_add_pPr()
    node = pPr.find(qn("w:ind"))
    if node is None:
        node = OxmlElement("w:ind")
        pPr.append(node)
    node.set(qn("w:left"), left)
    node.set(qn("w:leftChars"), left_chars)
    node.set(qn("w:right"), right)
    node.set(qn("w:firstLine"), first)
    node.set(qn("w:firstLineChars"), first_chars)


def paint(run, size_pt, bold, italic):
    run.bold = bold
    run.italic = italic
    run.font.name = "Times New Roman"
    run.font.size = Pt(size_pt)
    rPr = run._element.get_or_add_rPr()
    rFonts = rPr.find(qn("w:rFonts"))
    if rFonts is None:
        rFonts = OxmlElement("w:rFonts")
        rPr.append(rFonts)
    for attr in ("w:ascii", "w:hAnsi", "w:cs", "w:eastAsia"):
        rFonts.set(qn(attr), "Times New Roman")
    lang = rPr.find(qn("w:lang"))
    if lang is None:
        lang = OxmlElement("w:lang")
        rPr.append(lang)
    lang.set(qn("w:val"), "ru-RU")
    lang.set(qn("w:eastAsia"), "ru-RU")


def add_para(doc, text, *, kind):
    paragraph = doc.add_paragraph()
    paragraph.paragraph_format.widow_control = True
    if kind == "chapter":
        paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
        spacing(paragraph, before=227, after=227)
        indent(paragraph, first="794", first_chars="248")
        paint(paragraph.add_run(text), 16, True, False)
    elif kind == "sub":
        paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
        spacing(paragraph, before=227, after=567)
        indent(paragraph, first="793", first_chars="283")
        paint(paragraph.add_run(text), 14, True, False)
    else:
        paragraph.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        spacing(paragraph, before=0, after=0)
        indent(paragraph)
        paint(paragraph.add_run(text), 14, True, True)
    return paragraph


