def main():
    doc = Document()
    section = doc.sections[0]
    section.page_width = Twips(11906)
    section.page_height = Twips(16838)
    section.top_margin = Twips(850)
    section.bottom_margin = Twips(1531)
    section.left_margin = Twips(1701)
    section.right_margin = Twips(625)
    section.header_distance = Twips(708)
    section.footer_distance = Twips(708)

    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal.font.size = Pt(14)
    normal.font.bold = True
    normal.font.italic = True
    rPr = normal.element.get_or_add_rPr()
    rFonts = rPr.find(qn("w:rFonts"))
    if rFonts is None:
        rFonts = OxmlElement("w:rFonts")
        rPr.append(rFonts)
    for attr in ("w:ascii", "w:hAnsi", "w:cs", "w:eastAsia"):
        rFonts.set(qn(attr), "Times New Roman")

    core = doc.core_properties
    core.title = "Анализ предметной области и техническое задание. ALONG"
    core.subject = "Курсовая работа, анализ и техническое задание"
    core.language = "ru-RU"

    for kind, text in CHAPTERS:
        add_para(doc, text, kind=kind)

    body = doc.element.body
    first = body.find(qn("w:p"))
    texts = [] if first is None else first.findall(".//" + qn("w:t"))
    if first is not None and not any((t.text or "").strip() for t in texts):
        body.remove(first)

    doc.save(OUT)
    chars = sum(len(text) for _, text in CHAPTERS)
    print("saved", OUT)
    print("chars", chars)
    print("paras", len(CHAPTERS))


if __name__ == "__main__":
    main()
